    /// never wider than the request asked (invalid). A scope narrower than destructive is part of the step-up target,
    /// so an approval for one scope never pairs another.
    case devicePairingApprove = "device.pairing.approve"
    /// Close the caller's own pairing window; its requests expire. any: whoever's window is open (super admins only).
    case devicePairingClose = "device.pairing.close"
    /// Deny a pending request; the device is told it was declined.
    case devicePairingDeny = "device.pairing.deny"
    /// Open a 10-minute pairing window owned by the caller (reopening extends it). One window per node: conflict while
