    case deviceScopeSet = "device.scope.set"
    /// The server key's SPKI hash (the pin). A next key is never announced: a new server key means pairing again.
    case deviceServerIdentity = "device.server.identity"
    /// The email provider settings, the operator email policy and which provider secrets are stored.
    case emailConfigGet = "email.config.get"
    /// Merge-patch the email and operator_emails settings sections (RFC 7386; other sections are ignored) and save them
