    case emailConfigUpdate = "email.config.update"
    /// Operator email delivery history, newest first.
    case emailHistory = "email.history"
    /// Store provider credentials in the secrets manager: resend needs api_key; ses takes access_key_id and/or
    /// secret_access_key (at least one). Values are write-only.
    case emailProviderSecretSet = "email.provider.secret.set"
    /// Send (or, with dry_run, only render and record) a test email. Without to, a dry run goes to the first alerts
