    case fsChangesSubscribe = "fs.changes.subscribe"
    /// Stop following vaults by push (fs.changes.subscribe); without vault_ids, all of them.
    case fsChangesUnsubscribe = "fs.changes.unsubscribe"
    /// Create a directory (Touch on the path).
    case fsDirCreate = "fs.dir.create"
    /// List a directory (List on the path). Children the caller cannot Lookup are left out, as in FUSE readdir, and so
    /// is what they hold from child folders' size and counts and the folder's own size.
    case fsDirList = "fs.dir.list"
    /// Share sessions only: drop a transfer.
    case fsDownloadCancel = "fs.download.cancel"
    /// Share sessions only: read the next chunk (base64).
    case fsDownloadChunk = "fs.download.chunk"
    /// Share sessions only: start a chunked download of a file inside the share.
    case fsDownloadStart = "fs.download.start"
    /// Copy an entry or tree: Copy on every source, Read on source files, Write (files) or Touch (directories) at each
