    case fsEntryMove = "fs.entry.move"
    /// Rename an entry: Rename on the source; into another folder also Write (files) or Touch (directories) at the
    /// destination, for the entry and everything it carries.
    case fsEntryRename = "fs.entry.rename"
    /// fs.dir.list for console sessions; in a share session the share's view of the directory.
    case fsList = "fs.list"
    /// One entry's metadata (Lookup on the path). A folder's size covers only what the caller can Lookup, as in
