    case fsMetadata = "fs.metadata"
    /// Abort the session's active ws upload.
    case fsUploadCancel = "fs.upload.cancel"
    /// Finish the session's active ws upload.
    case fsUploadFinish = "fs.upload.finish"
    /// Start a chunked ws upload (Write on the path). The console uploads over HTTP instead (POST /upload/session);
    /// this is the native ws transfer.
    case fsUploadStart = "fs.upload.start"
    /// Create a group.
    case groupAdd = "group.add"
    /// One group by id.
    case groupGet = "group.get"
    /// One group by name.
    case groupGetByName = "group.get.byName"
    /// Add a user to a group.
    case groupMemberAdd = "group.member.add"
    /// Remove a user from a group.
    case groupMemberRemove = "group.member.remove"
    /// Delete a group.
    case groupRemove = "group.remove"
    /// Patch a group: name, description and linux_gid are each optional.
    case groupUpdate = "group.update"
    /// Every group for group viewers; otherwise only the caller's own groups.
    case groupsList = "groups.list"
    /// The groups a user belongs to.
    case groupsListByUser = "groups.list.byUser"
    /// "I have seen this occurrence": marks an active finding acknowledged. The mark ends when the finding clears or
    /// its severity rises. Refused (conflict) when the class is not active or is silenced. Needs admin.stats.manage;
    /// recorded in the audit trail. Never available to agents or scoped devices.
    case healthFindingAcknowledge = "health.finding.acknowledge"
    /// "Do not tell me about this class": silences a finding class, active or not, for a time or until it is turned
    /// back on. A silence does not cover a severity above the one it was set for. Needs admin.stats.manage; recorded in
    /// the audit trail. Never available to agents or scoped devices.
    case healthFindingSilence = "health.finding.silence"
    /// Turns a finding class back on: removes its silence or acknowledgement. Refused (not_found) when it has neither.
    /// Needs admin.stats.manage; recorded in the audit trail. Never available to agents or scoped devices.
    case healthFindingUnsilence = "health.finding.unsilence"
    /// The health findings that are active now, each with what an operator said about it (active, acknowledged,
    /// silenced), whether it is worth a notification, and its remedies; the silences whose class is not active; and the
    /// counts with and without acknowledged and silenced findings. Severity is never changed by a mark. Needs
    /// admin.stats.view.
    case healthFindingsList = "health.findings.list"
    /// Follow the health findings by push (design/health/findings.md §6): whenever the findings or their state change,
    /// the session gets an unsolicited frame {"command": "health.changed", "data": {"revision", "overall_status",
