             "recovery_policy_account_managed", "managed_vault_account_key", "step_up_required", "recovery_cooldown"]
        case .vaultRecover:
            ["denied", "invalid", "not_found", "conflict", "unauthorized", "recover_requires_device",
             "salvage_required", "rollback", "fork", "kit_vault_mismatch", "export_vault_mismatch",
             "recovery_material_mismatch", "no_key_material", "vault_unknown", "step_up_required", "recovery_cooldown"]
        case .vaultRemoteAttach:
            ["denied", "invalid", "not_found", "conflict", "unauthorized", "key_rotation_running",
             "key_salvage_running", "legacy_content", "key_version_missing", "key_version_unattested",
             "recovery_material_missing", "bucket_listing_failed", "bucket_not_empty", "bucket_probe_failed",
             "bucket_capability_insufficient", "bucket_holds_this_vault", "step_up_required", "recovery_cooldown"]
        case .vaultRemoteDetach:
            ["denied", "invalid", "not_found", "conflict", "unauthorized", "attach_running", "layout_migration_running",
             "key_rotation_running", "key_salvage_running", "legacy_content", "key_version_missing",
             "event_sync_active", "sync_conflicts_open", "step_up_required", "recovery_cooldown"]
        case .vaultStorageProbe:
            ["denied", "invalid", "not_found", "unauthorized", "bucket_probe_failed"]
        }
    }

    /// The NeedsConfirmation refusals it can answer with (`WsError.needsConfirmation`) and the payload member
    /// a resend sets to accept each; `confirmation(_:)` looks one up by code.
    public var confirmations: [WsConfirmation] {
        switch self {
        case .authUserDelete:
            [
                WsConfirmation(
                    code: "user_delete", acceptField: "confirm",
                    summary:
                        """
                        The account (and the vaults it owns unless transfer_to is set) would be deleted: resend with\
                         confirm once the person agrees.
                        """
                ),
            ]
        case .recoveryPointDelete:
            [
                WsConfirmation(
                    code: "recovery_point_delete", acceptField: "confirm",
                    summary: "Deleting a snapshot or local version can't be undone: resend with confirm."
                ),
            ]
        case .recoveryRestore:
            [
                WsConfirmation(
                    code: "recovery_restore", acceptField: "token",
                    summary:
                        """
                        The plan's token is missing or wrong: resend with the token recovery.plan returned (shown with\
                         the plan's create / overwrite / remove counts).
                        """
                ),
                WsConfirmation(
                    code: "recovery_plan_expired", acceptField: nil,
                    summary: "The plan expired (30 minutes): plan again with recovery.plan and restore the new plan."
                ),
                WsConfirmation(
                    code: "recovery_unverified_version", acceptField: "accept_unverified",
                    summary:
                        """
                        Some versions were found in the bucket, not written by Vaulthalla: resend with\
                         accept_unverified only if the person trusts them.
                        """
                ),
            ]
        case .s3GatewayBucketsCreateRemoteCache:
            [
                WsConfirmation(
                    code: "encryption_waiver", acceptField: "accept_encryption_waiver",
                    summary:
                        """
                        The upstream bucket already holds data Vaulthalla did not write: resend with\
                         accept_encryption_waiver once the person accepts.
                        """
                ),
            ]
        case .s3GatewayUpstreamProfilesCreate, .s3GatewayUpstreamProfilesUpdate:
            [
                WsConfirmation(
                    code: "upstream_profile_versioning", acceptField: "accept_versioning",
                    summary:
                        """
                        The profile's buckets will keep old versions on Backblaze B2, billed until they expire: resend\
                         with accept_versioning once the person accepts.
                        """
                ),
            ]
        case .storageVaultAdd:
            [
                WsConfirmation(
                    code: "encryption_waiver", acceptField: "accept_encryption_waiver",
                    summary:
                        """
                        The bucket already holds data Vaulthalla did not write (or encryption is being switched on\
                         over it): resend with accept_encryption_waiver once the person accepts.
                        """
                ),
                WsConfirmation(
                    code: "upstream_adoption", acceptField: "provision.accept_adoption",
                    summary:
                        """
                        provision mode adopt (or an existing unmanaged bucket) needs consent to adopt the bucket:\
                         resend with provision.accept_adoption.
                        """
                ),
            ]
        case .storageVaultRemove:
            [
                WsConfirmation(
                    code: "vault_upstream_key_loss", acceptField: "accept_key_loss",
                    summary:
                        """
                        The vault key was never exported and its S3 data would become unreadable: resend with\
                         accept_key_loss once the person accepts.
                        """
                ),
                WsConfirmation(
                    code: "vault_delete_now", acceptField: "confirm_now",
                    summary: "Deleting now skips the restore window: resend with confirm_now."
                ),
            ]
        case .storageVaultUpdate:
            [
                WsConfirmation(
                    code: "encryption_waiver", acceptField: "accept_encryption_waiver",
                    summary:
                        """
                        The bucket already holds data Vaulthalla did not write (or encryption is being switched on\
                         over it): resend with accept_encryption_waiver once the person accepts.
                        """
                ),
            ]
        case .upstreamBucketCleanup:
            [
                WsConfirmation(
                    code: "upstream_cleanup", acceptField: "confirm_token",
                    summary:
                        """
                        The confirm_token is missing, expired or no longer matches the bucket: run\
                         upstream.bucket.cleanup.preflight again and resend its confirm_token.
                        """
                ),
            ]
        case .upstreamBucketLifecycleSet:
            [
                WsConfirmation(
                    code: "upstream_destructive_lifecycle", acceptField: "accept_destructive",
                    summary: "Expiration deletes objects: resend with accept_destructive once the person accepts."
                ),
            ]
        case .upstreamBucketUnprotect:
            [
                WsConfirmation(
                    code: "upstream_unprotect", acceptField: "confirm",
                    summary: "Removing a bucket lock lets Vaulthalla act on the bucket again: resend with confirm."
                ),
            ]
        case .vaultKeysImport:
            [
                WsConfirmation(
                    code: "vault_key_import", acceptField: "confirm_name",
                    summary:
                        """
                        mode recover: the import would re-seal the listed key versions under this host's vault master\
                         (the error text says which): resend with confirm_name set to the vault's name (a string, not\
                         a flag) once the person typed it.
                        """
                ),
                WsConfirmation(
                    code: "vault_key_salvage", acceptField: "confirm_name",
                    summary:
                        """
                        Every mode salvage request that would write. It would create a fresh key version and\
                         re-encrypt every file the supplied key decrypts under it (the error text says which versions;\
                         files it can't decrypt are reported unrecoverable), and restore any attested versions as\
                         recover does; when no version needs salvage the text says so and only the restore happens.\
                         Resend with confirm_name set to the vault's name once the person typed it.
                        """
                ),
            ]
        case .vaultRecover:
            [
                WsConfirmation(
                    code: "vault_recover_salvage", acceptField: "confirm_name",
                    summary:
                        """
                        A salvage restore would create a fresh key on this node and re-encrypt every file the supplied\
                         keys decrypt (the text says which versions); resend with confirm_name set to the restored\
                         vault's name once the person typed it.
                        """
                ),
            ]
        case .vaultRecoverySuspend:
            [
                WsConfirmation(
                    code: "recovery_versioning_suspend", acceptField: "confirm",
                    summary: "Suspending versioning on the bucket: resend with confirm (existing versions are kept)."
                ),
            ]
        case .vaultRecoveryUpdate:
            [
                WsConfirmation(
                    code: "recovery_versioning_disclosure", acceptField: "disclosure_token",
                    summary:
                        """
                        Provider versioning needs the cost disclosure: show vault.recovery.disclosure and resend its\
                         disclosure_token (valid 10 minutes, and only while the figures are unchanged).
                        """
                ),
                WsConfirmation(
                    code: "recovery_versioning_unpriced", acceptField: "accept_unpriced",
                    summary:
                        "Some costs can't be priced: resend with accept_unpriced once the person accepts unknown costs."
                ),
                WsConfirmation(
                    code: "recovery_retention_shorten", acceptField: "accept_retention_shortening",
                    summary: "A shorter retention deletes history sooner: resend with accept_retention_shortening."
                ),
                WsConfirmation(
                    code: "upstream_adoption", acceptField: "accept_adoption",
                    summary:
                        "The vault's bucket is not managed by Vaulthalla yet: resend with accept_adoption to adopt it."
                ),
            ]
        default: []
        }
    }

    /// The command book's description.
    public var summary: String {
        switch self {
        case .auditExport:
            """
            The events in [since_us, until_us) as NDJSON (vh-audit-export-v1: a header line, the events with their\
             hashes, then the signed heads that cover them), verifiable offline. Up to 32 MiB; use `vh audit export`\
             for more. Needs admin.audits.view; recorded as audit.export.
            """
        case .auditList:
            """
            The tamper-evident audit trail, newest first, filtered. Needs admin.audits.view; the first page is itself\
             recorded (audit.view).
            """
        case .auditVerify:
            """
            Recomputes the whole retained hash chain and checks every signed head (signature, and that the chain still\
             holds the hash it signed). Needs admin.audits.view; recorded as audit.verify (or audit.verify.failed).
            """
        case .authActivity:
            """
            Report that the person at the console is using it (keyboard, pointer, scroll), at most about once a\
             minute. It resets the session's idle sign-out clock\
             (services.connection_lifecycle_manager.idle_timeout_minutes) with the server's own time; background\
             requests never do. An idle session is refused like any other expired one.
            """
        case .authApprovalApprove:
            """
            Approve a device's request with a passkey, nothing else: a TOTP code or a password is refused (invalid),\
             and an account without a usable passkey gets passkey_required (do the action in the console instead).\
             Without credential: answers webauthn.publicKey (a challenge bound to this session and this request, 120\
             s) for navigator.credentials.get(); with credential (a UV assertion over it): approves, and the device's\
             next device.approval.status makes its grant. approval_failed {attempts_remaining}: the assertion didn't\
             hold; the fifth failure within 15 minutes signs this session out. not_found: expired or already answered.
            """
        case .authApprovalDeny:
            "Decline a device's request; its device.approval.status answers denied."
        case .authApprovalList:
            """
            The signed-in account's open requests from its paired devices (device.approval.request), oldest first:\
             what each asks for (family, target), the device's own summary, and when it expires. A new request also\
             arrives as an unsolicited frame {"command": "auth.approval.pending", "data": {approval_id, device: {id,\
             name}, family, target, summary, expires_at}} on every console session of the account. Web sessions only:\
             a device is refused.
            """
        case .authIsAuthenticated:
            "Whether the envelope token is a valid session for this socket."
        case .authLogin:
            """
            Sign in with a username and password. The access token comes back in the response envelope (`token`), the\
             refresh token as an HttpOnly cookie set at the handshake. A connection signs in once: one that already\
             has a user (signed in, or restored from its cookie) is refused with data.code already_signed_in; sign in\
             again on a new connection. A password alone signs in (aal 1, amr ["pwd"]) only an account with no factor\
             that need not have MFA. Otherwise the right password answers ERROR mfa_required (a factor is enrolled:\
             finish with auth.mfa.verify) or mfa_enrollment_required (the MFA policy requires one and there is none:\
             set it up with the enrollment commands), and the connection is pending: not signed in, no access token,\
             no session row, so auth.refresh, a reconnect, another tab and the HTTP lanes all refuse it. It may run\
             only auth.mfa.verify, auth.mfa.cancel and auth.logout (plus the enrollment commands while enrolling) and\
             ends after 5 minutes (10 enrolling), 5 failed factors or with the socket. mfa_unavailable: the account's\
             factors can't be used on this server. data.pending is {kind: "mfa" | "enrollment", expires_at (Unix\
             seconds), methods: ["webauthn" | "totp" | "recovery_code"], attempts_remaining, webauthn?: {publicKey:\
             PublicKeyCredentialRequestOptionsJSON}}.
            """
        case .authLogout:
            "End the session (access and refresh tokens)."
        case .authMfaAdminRequire:
            """
            Require MFA for one account whatever the policy level (or stop requiring it; the policy may still).\
             Applies at the account's next request: a session signed in without a second factor is signed out. Answers\
             its status. identity.admin step-up. Who: whoever may reset the account's password (admin.identities.users\
             or .admins reset-password, within their own permissions); a super admin's MFA only another super admin;\
             never your own account here (Account > Security, or `vh user mfa` on the server).
            """
        case .authMfaAdminReset:
            """
            Reset an account that lost every factor: its passkeys and authenticator apps are disabled (kept for the\
             audit trail), its recovery codes voided, every session signed out, the key-backup grants of its paired\
             devices revoked (the devices stay paired), and it must set up a new factor at its next sign-in, inside\
             the recovery cooldown. The account and the security recipients are notified; audited as\
             auth.mfa.admin.reset. account.credentials step-up. Who: whoever may reset the account's password\
             (admin.identities.users or .admins reset-password, within their own permissions); a super admin's MFA\
             only another super admin; never your own account here (Account > Security, or `vh user mfa` on the\
             server).
            """
        case .authMfaAdminStatus:
            """
            Another account's MFA: whether it must have MFA and why, its factors (no secrets), recovery codes left,\
             the recovery cooldown and the last reset. Who: whoever may reset the account's password\
             (admin.identities.users or .admins reset-password, within their own permissions); a super admin's MFA\
             only another super admin; never your own account here (Account > Security, or `vh user mfa` on the\
             server).
            """
        case .authMfaCancel:
            "End a pending sign-in now; the connection is anonymous again (sign in again with the password)."
        case .authMfaFactorRemove:
            """
            Remove one of the caller's factors (named by kind and id): it is disabled, kept for the audit trail and\
             never usable again, and the account's other web sessions are signed out (one of them may hold it).\
             mfa_last_factor: it is the last usable factor of an account that must have MFA (add another first).\
             account.credentials step-up.
            """
        case .authMfaFactorRename:
            "Rename one of the caller's factors (named by kind and id)."
        case .authMfaRecoveryAcknowledge:
            """
            The person saved the codes of batch_id: they come into force and the previous batch stops working. On a\
             pending enrollment this completes the sign-in (aal 2, amr ["pwd", the new factor's]) and answers the\
             user, with the access token in the envelope.
            """
        case .authMfaRecoveryGenerate:
            """
            Make ten new recovery codes, shown once. They replace the current ones only when acknowledged. The account\
             needs a factor (invalid otherwise). Replacing codes that are in force is account.credentials step-up\
             (except on the recovery-code session spending them).
            """
        case .authMfaStatus:
            """
            The caller's MFA: whether the policy requires it and why (policy admins: the super admin and accounts\
             whose admin role may add, edit or delete users or admins or reset their passwords, add, edit or delete\
             admin or vault roles, edit any settings section, or export or rotate encryption keys; policy all: every\
             account; user_required: set for this account), whether passkeys are configured, the factors, the recovery\
             codes, and the recovery cooldown. Web sessions only (a paired device is denied).
            """
        case .authMfaTotpEnrollConfirm:
            """
            Finish the authenticator setup with its current code (one step of drift either way). The account's first\
             factor answers its recovery codes too. invalid: the code didn't match; not_found: the setup expired or is\
             finished.
            """
        case .authMfaTotpEnrollStart:
            """
            Start setting up an authenticator app (RFC 6238, SHA-1, 6 digits, 30 s). The secret and otpauth URI are\
             shown once (the console draws the QR code itself); the factor is unusable until\
             auth.mfa.totp.enroll.confirm, within 10 minutes. Starting again replaces an unfinished setup.
            """
        case .authMfaVerify:
            """
            Finish a pending sign-in with a second factor: {method: "webauthn", credential} (a UV assertion over the\
             pending challenge), or {method: "totp" | "recovery_code", code}. Success signs the connection in: one\
             session row at aal 2 with amr ["pwd", "hwk" | "swk" | "otp" | "rec"], the access token in the envelope. A\
             recovery code signs every other web session of the account out (paired devices are not touched), starts\
             the recovery cooldown, revokes the key-backup grants of the account's paired devices (they stay paired\
             and are listed for the person to revoke) and answers `recovery`. Refusals: mfa_invalid\
             {attempts_remaining, pending?} (the 5th ends the sign-in), mfa_expired (start again with the password),\
             rate_limited {retry_after} (the account's 5th failed factor in a streak waits 1 minute, each further one\
             doubles it up to 15; never a lock), mfa_required {pending} for {method: "webauthn"} without a credential:\
             a fresh passkey challenge, not an attempt. data.pending is {kind: "mfa" | "enrollment", expires_at (Unix\
             seconds), methods: ["webauthn" | "totp" | "recovery_code"], attempts_remaining, webauthn?: {publicKey:\
             PublicKeyCredentialRequestOptionsJSON}}.
            """
        case .authMfaWebauthnRegisterFinish:
            """
            Verify and store the passkey (attestation none or packed self; UV required). The account's first factor\
             answers its recovery codes too; a pending enrollment then finishes with auth.mfa.recovery.acknowledge.\
             invalid: the ceremony didn't verify; not_found: the registration expired (120 s) or was used.
            """
        case .authMfaWebauthnRegisterOptions:
            """
            Start registering a passkey ("Passkey / Security key": 1Password, the device's passkey manager, a security\
             key) on the caller's account, or as the first factor of a pending enrollment. Pass publicKey to\
             navigator.credentials.create() and the result to auth.mfa.webauthn.register.finish with registration_id.\
             invalid when passkeys are not configured (auth.webauthn.rp_id).
            """
        case .authPasskeyLogin:
            """
            Finish a passkey sign-in with the assertion over an auth.passkey.options challenge of this connection. The\
             assertion must carry userHandle, equal to the account's own WebAuthn handle for that credential, and user\
             verification. Success signs the connection in: one session row at aal 2 with amr ["hwk"] (a device-bound\
             passkey or security key) or ["swk"] (a synced passkey), the access token in the envelope. Every failure\
             (an unknown, suspended or foreign passkey, another server's, no user verification, a spent or expired\
             challenge, an account that can't sign in) is the same error; the challenge is spent either way.\
             already_signed_in on a signed-in connection.
            """
        case .authPasskeyOptions:
            """
            Start signing in with a passkey alone, no username or password first: a challenge for\
             navigator.credentials.get() on this connection, with an empty allowCredentials (the browser or passkey\
             manager offers the passkeys it holds for this server) and user verification required. It names no\
             account, so the answer is the same for every caller but for its challenge. Anonymous web connections\
             only: already_signed_in on a signed-in one; a paired device and a pending sign-in can't run it. invalid\
             when passkeys are not configured (auth.webauthn.rp_id). Rate limited to 30 a minute per client address;\
             rate_limited when 10,000 sign-in challenges are open.
            """
        case .authRefresh:
            "Issue a new access token from the envelope token or the refresh cookie."
        case .authRegister:
            "Create a user. role is an admin role name or id; the password is required (only the CLI generates one)."
        case .authSecurityStatus:
            """
            Security posture warning for the signed-in account: the super admin's initial password file while the\
             generated password is still in use, else null.
            """
        case .authSessionsList:
            """
            The caller's signed-in web sessions (one per browser: its tabs share one), most recent sign-in first:\
             live, unexpired and not past the idle sign-out. Ids are opaque handles for auth.sessions.revoke, never\
             the refresh token's id, and change when the daemon restarts.
            """
        case .authSessionsRevoke:
            """
            Sign out one of the caller's sessions (id from auth.sessions.list; the current one included) or every\
             other one (all_others). Revoked sessions end at once: their sockets close and their cookies stop working\
             for previews, downloads and uploads. Give exactly one of id and all_others (else invalid); an id that is\
             not one of the caller's live sessions is not_found.
            """
        case .authStepupBegin:
            """
            Start confirming a sensitive change that answered step_up_required: name its family and, for keys,\
             device.trust, data.destroy and connector.trust, the target the refusal named. Answers the methods the\
             account can use (webauthn: pass webauthn.publicKey to navigator.credentials.get(); password_totp: the\
             password and an authenticator code together; password: only for an account that need not have MFA and has\
             no factor, never for a target-bound family: keys, device.trust, data.destroy, connector.trust) and a\
             ceremony id valid for 120 s. A new begin replaces the open ceremony. step_up_unavailable: the account has\
             nothing that can confirm this family (add a passkey or an authenticator app). Web sessions only: a paired\
             device is denied.
            """
        case .authStepupFinish:
            """
            Answer the ceremony: {method: webauthn, credential} (a UV assertion over its challenge), {method:\
             password_totp, password, code} or {method: password, password}. On success this session holds a grant for\
             the family (and target): family grants last max_age_seconds, target-bound ones are spent by one use. Then\
             resend the refused request. step_up_failed {attempts_remaining}: the answer didn't hold; the fifth\
             failure within 15 minutes signs this session out. not_found: the ceremony expired or was used (begin\
             again). Recovery codes, refresh tokens and Desktop mTLS never satisfy a step-up.
            """
        case .authUserChangePassword:
            "Change (own, with old_password) or reset (another user's) a password."
        case .authUserDelete:
            """
            Delete a user. Without confirm the reply is a refusal with data.code 'user_delete' and the question to\
             ask. The user's vaults are destroyed unless transfer_to names who gets them.
            """
        case .authUserGet:
            "One user with its full roles and permissions."
        case .authUserGetByName:
            "One user by name."
        case .authUserUpdate:
            """
            Patch a user (the caller when id is absent). Role changes and deactivation end the account's sessions.\
             linux_uid, updated_by, protected, is_protected, system_only and password are refused.
            """
        case .authUsersList:
            "Users visible to the caller, slim projection (admin_role without permissions)."
        case .cloudKeyConfirm:
            """
            Pin the waiting account recovery key: the first one after linking, or a replacement. The fingerprint must\
             be the waiting generation's (a device derives it from the key it holds); a mismatch pins nothing\
             (cloud_key_mismatch). Super admins; a paired device only (cloud_key_requires_device otherwise), with a\
             keys step-up.
            """
        case .cloudKeyRefresh:
            """
            Ask for a check of the account recovery key and recovery policy now. The check runs in the background\
             (this answers at once, with the status as it stands); a signed rotation is followed, anything else waits\
             for a confirmation. Super admins.
            """
        case .cloudKeyStatus:
            """
            The linked account's recovery key as this server pinned it: the pinned generation and fingerprint, a key\
             waiting for confirmation, the accepted recovery policy, the vaults it covers and the last check. Reads\
             the database only; public values only. Super admins or the encryption-key View permission.
            """
        case .cloudLinkStatus:
            """
            Whether this server is linked to an account, and as what: installation, deployment, account public id and\
             the pinned account recovery key. Reads the database only. Super admins and the encryption-key View\
             permission see the identifiers; any other session sees linked alone.
            """
        case .cloudRelayDisable:
            """
            Switch the relay off: the connection and every relayed session close at once; paired browsers stay paired\
             (device.revoke unpairs one). Super admins.
            """
        case .cloudRelayEnable:
            """
            Switch the relay on for this linked server: browsers paired through the cloud relay reach it (read only),\
             and relayed pairing requests can arrive while a pairing window is open. The account holder's switch at\
             the cloud must be on too. Super admins; conflict when not linked.
            """
        case .cloudRelayStatus:
            """
            The relay's local switch and the outbound connection as the service last saw it (connected only after the\
             relay admitted it), when it must renew, the last error and the relayed streams. Reads the database and\
             the service's memory, no cloud call. Super admins or the admin cloud View permission.
            """
        case .cloudStorageBillingHandoff:
            """
            The address of the account's billing page (checkout: choose a plan; portal: manage it), to open in a\
             browser; short-lived and never stored. The service polls the account's state fast for a few minutes\
             afterwards. The admin cloud Billing permission.
            """
        case .cloudStorageEndedConfirm:
            """
            Confirm that the account's plan ended: managed vaults become local in place now (files held only in their\
             buckets are listed as lost; nothing local is deleted) instead of after cloud.storage.ended_grace_hours of\
             continuous `ended` reports. Conflict unless the service reports `ended`. The admin cloud Storage\
             permission.
            """
        case .cloudStorageNewVaults:
            """
            Whether vaults created from now on use managed storage by default (on unless turned off). The admin cloud\
             Storage permission.
            """
        case .cloudStorageOfferAccept:
            """
            Accept the offer for vaults that existed when managed storage became available: the listed ones or,\
             without vault_ids, every offered vault (their switches go on). Nothing is uploaded before this. The admin\
             cloud Storage permission and each vault's admin Edit permission.
            """
        case .cloudStorageOfferDecline:
            """
            Decline the offer for the listed vaults (or every one still offered): they stay local; each can be\
             switched on later. The admin cloud Storage permission.
            """
        case .cloudStorageRotate:
            """
            Ask for a new bucket key for a vault in managed storage (the service exchanges, probes and acknowledges\
             it; the old key is revoked then). The admin cloud Storage permission and the vault's admin Edit\
             permission.
            """
        case .cloudStorageStatus:
            """
            Managed storage on this server: whether it is available (linked, the account recovery key confirmed, the\
